    def test_a_note_folded_into_a_carry_on_reaches_every_later_fresh_session(self):
        # #677 (Claude's audit of main): round_asks skipped a carry-on whole, the note folded into
        # it included, so the second handover's session never got the note, and steer_taken
        # already counted it, so nothing said it went missing
        from workbench import lessons, runner
        t = store.Task("t-fold")
        t.dir.mkdir(parents=True)
        store.write_json(t.dir / "task.json", {"name": "t-fold", "created_at": store.now()})
        t.set_status(window=32768, step_round=1, round=2)
        for r, text in ((1, "Write the answer."), (2, lessons.FEEDBACK_HEAD + " 1. Use a heap.")):
            t.round_dir(r).mkdir(parents=True)
            t.round_dir(r).joinpath("prompt.md").write_text(text)
        store.append_jsonl(t.dir / "steer.jsonl", {"ts": store.now(), "text": "Use the v2 API, not v1"})
        rnd = {"full": 26000, "texts": ["Halfway there."]}
        runner._full_round(t, 2, rnd)                       # the note goes with the first carry-on
        self.assertIn("Use the v2 API", store.round_prompt(t, 3).read_text())
        runner._full_round(t, 3, rnd)                       # and the second still carries it
        self.assertIn("Use the v2 API", store.round_prompt(t, 4).read_text())
        asks = runner.round_asks(t, 4)
        self.assertEqual(sum("Use the v2 API" in a for a in asks), 1)   # once, not per handover
        self.assertTrue(asks[0].startswith(lessons.FEEDBACK_HEAD))
        store.append_jsonl(t.dir / "steer.jsonl", {"ts": store.now(), "text": "And log it."})
        runner._early_notes(t, 4)                           # a note as round 4's model reloads
        self.assertIn("And log it.", "\n".join(runner.round_asks(t, 4)))

    def test_the_runners_nudge_is_never_one_of_what_a_later_fresh_session_was_asked(self):
        # #681 (Claude's audit of main): a nudge round's prompt ("Claude, your reviewer,
        # interrupted you… thinking for 12 minutes") went to every later fresh session in the
        # step under "What you were asked to do", and a fresh round after it was stopped at its
        # first long think "even after a nudge"
        from workbench import lessons, runner
        t = store.Task("t-nudged")
        t.dir.mkdir(parents=True)
        store.write_json(t.dir / "task.json", {"name": "t-nudged", "created_at": store.now()})
        t.set_status(step_round=1, round=2)
        for r, text in ((1, "Write the answer."), (2, lessons.FEEDBACK_HEAD + " 1. Use a heap.")):
            t.round_dir(r).mkdir(parents=True)
            t.round_dir(r).joinpath("prompt.md").write_text(text)
        nudge = runner.NUDGE.format(mins=12)
        store.append_jsonl(t.dir / "steer.jsonl", {"ts": store.now(), "text": nudge, "now": True,
                                                   "by": "workbench"})
        runner._steer_round(t, 2, True)
        self.assertIn(nudge, store.round_prompt(t, 3).read_text())    # the agent still gets it
        self.assertEqual(runner.round_asks(t, 3), [lessons.FEEDBACK_HEAD + " 1. Use a heap."])
        store.append_jsonl(t.dir / "steer.jsonl", {"ts": store.now(), "text": nudge, "now": True,
                                                   "by": "workbench"})
        store.append_jsonl(t.dir / "steer.jsonl", {"ts": store.now(), "text": "Use v2.", "now": True})
        runner._steer_round(t, 3, True)                    # Claude's note beside a nudge is kept
        asks = "\n".join(runner.round_asks(t, 4))
        self.assertIn("Use v2.", asks)
        self.assertNotIn("without a tool call", asks)
        self.assertTrue(runner.renudged({"nudged_round": 3, "session": "ses_1"}, 4))
        self.assertFalse(runner.renudged({"nudged_round": 3, "session": None}, 4))  # a fresh one
        self.assertFalse(runner.renudged({"nudged_round": 2, "session": "ses_1"}, 4))

    def test_a_fresh_session_after_a_feedback_round_still_carries_the_feedback(self):
        # Between rounds, an auto-fix round that started fresh carried only the failing tests:
        # the agent fixed them and reported done with the feedback never made (the 2026-11-16
        # incident, on the between-rounds path).
        self.start("t-c11", "ok", "--test", TEST_CMD)
        wait_phase("t-c11", {"review"})
        t = store.Task("t-c11")
        from workbench import lessons
        for n, text in ((2, f"{lessons.FEEDBACK_HEAD} Make exactly these changes:\n\nRENAME foo TO bar"),
                        (3, runner.auto_fix_prompt({"exit": 1, "tail": "FAIL x"}, TEST_CMD)),
                        (4, runner.CARRY_ON.format(asked="", last="> my last words"))):
            t.round_dir(n).mkdir(parents=True)
            t.round_dir(n).joinpath("prompt.md").write_text(text)
        runner._start_fresh(t, 3, "the last session was 70% full")
        now = t.round_dir(3).joinpath("prompt.md").read_text().split("## Now")[1]
        self.assertIn("RENAME foo TO bar", now)
        self.assertIn("The acceptance tests fail", now)
        runner._start_fresh(t, 4, "the last session was 70% full")  # a carry-on has its asks
        self.assertIn("> my last words", t.round_dir(4).joinpath("prompt.md").read_text())

    def test_a_nudge_round_that_starts_fresh_still_carries_the_feedback_before_it(self):
        # #859 (the third 2026-11-21 audit): round_asks skips a nudge round, and _start_fresh
        # dropped the last ask as the round's own, the feedback: the fresh session got only
        # "you have been thinking for 12 minutes", found the tests green and reported done
        self.start("t-859", "ok", "--test", TEST_CMD)
        wait_phase("t-859", {"review"})
        t = store.Task("t-859")
        from workbench import lessons
        t.round_dir(2).mkdir(parents=True)
        t.round_dir(2).joinpath("prompt.md").write_text(f"{lessons.FEEDBACK_HEAD} 1. RENAME foo TO bar")
        t.set_status(round=2)
        store.append_jsonl(t.dir / "steer.jsonl", {"ts": store.now(), "now": True, "by": "workbench",
                                                   "text": runner.NUDGE.format(mins=12)})
        runner._steer_round(t, 2, True)
        runner._start_fresh(t, 3, "the last session was 70% full")
        now = t.round_dir(3).joinpath("prompt.md").read_text().split("## Now")[1]
        self.assertIn("RENAME foo TO bar", now)
        self.assertIn("thinking for 12 minutes", now)              # the nudge itself still goes
        # with Claude's note beside the nudge, the note is the round's own ask, said once
        t.round_dir(4).mkdir(parents=True)
        store.append_jsonl(t.dir / "steer.jsonl", {"ts": store.now(), "now": True, "by": "workbench",
                                                   "text": runner.NUDGE.format(mins=12)})
        store.append_jsonl(t.dir / "steer.jsonl", {"ts": store.now(), "now": True, "text": "Use v2."})
        runner._steer_round(t, 3, True)
        runner._start_fresh(t, 4, "the last session was 70% full")
        now = t.round_dir(4).joinpath("prompt.md").read_text().split("## Now")[1]
        self.assertIn("RENAME foo TO bar", now)
        self.assertEqual(now.count("Use v2."), 1)

    def test_a_step_that_keeps_filling_up_is_stopped_after_a_few_handovers(self):
        # A session that changed a file early and then filled up reading handed over again and
        # again, for hours, with Claude told nothing (the 2026-11-16 audit).
        self.start("t-c12", "refill")
        st = wait_phase("t-c12", {"review", "stuck", "failed"}, timeout=120)
        self.assertEqual((st["phase"], st["handovers"]), ("stuck", runner.HANDOVER_MAX))
        self.assertIn(f"handed over to a fresh session {runner.HANDOVER_MAX} times", st["last"])
        rows = [r for r in store.read_jsonl(store.home() / "notify.jsonl")[0] if r["task"] == "t-c12"]
        # one warning, at the handover before the last: one per handover from the second on woke
        # Claude to read "on course" and wait again (2026-11-17)
        warned = [r for r in rows if r["kind"] == "checkin" and "handover" in r["text"]]
        self.assertEqual(len(warned), 1)
        self.assertIn(f"handover {runner.HANDOVER_MAX - 1} this round", warned[0]["text"])
        self.assertEqual([r["kind"] for r in rows if r["kind"] != "checkin"], ["stuck"])

