class CheckoutVenv(Base):
    """#490 (the audit of 1.90): the user's activated venv, when it is their checkout's, stays out
    of the agent's environment, so the agent, the setup and the tests import the worktree."""
    TEST = ("python3 -c \"import mypkg, sys; print(mypkg.__file__); "
            "sys.exit(mypkg.VALUE != 'base')\"")

    def setUp(self):
        super().setUp()
        pkg = self.repo / "src" / "mypkg"
        pkg.mkdir(parents=True)
        (pkg / "__init__.py").write_text("VALUE = 'base'\n")
        (self.repo / ".gitignore").write_text(".venv/\n")
        subprocess.run(["git", "-C", str(self.repo), "add", "."], check=True)
        subprocess.run(["git", "-C", str(self.repo), "commit", "-qm", "pkg"], check=True)
        (pkg / "__init__.py").write_text("VALUE = 'user'\n")   # the user's own work in progress

    def venv(self, root: Path, editable: Path | None = None) -> Path:
        """A virtualenv at ``root``, active as `source bin/activate` leaves it; with ``editable``,
        a src-layout editable install of that directory (the .pth uv and hatch write)."""
        import venv
        venv.create(root, symlinks=True, with_pip=False)
        if editable:
            site = next(root.glob("lib/*/site-packages"))
            (site / "_mypkg.pth").write_text(f"{editable}\n")
        os.environ["VIRTUAL_ENV"] = str(root)
        os.environ["PATH"] = f"{root / 'bin'}{os.pathsep}{os.environ['PATH']}"
        return root

    def test_the_tests_import_the_worktree_not_the_checkout_its_editable_venv_points_at(self):
        user = self.venv(self.repo / ".venv", self.repo / "src")
        # what SKILL.md advises: the setup makes the worktree its own venv, editable into it
        setup = ("python3 -m venv --without-pip .venv && .venv/bin/python3 -c \"import os, site; "
                 "open(site.getsitepackages()[0] + '/_mypkg.pth', 'w').write(os.getcwd() + '/src')\"")
        out = self.start("t-venv", "ok", "--setup", setup, "--test", self.TEST, "--auto-fix", "0",
                         "--no-base-check")
        self.assertIn(f"note: the active Python environment {user} (inside the repo) is your "
                      "checkout's", out)
        st = wait_phase("t-venv", {"review"})
        task = store.Task("t-venv")
        said = task.round_dir(1).joinpath("tests.txt").read_text()
        self.assertTrue(st["tests"]["ok"], said)                  # VALUE 'base', the worktree's
        self.assertIn(str(task.worktree / "src" / "mypkg"), said)
        env = runner.agent_env(task)
        self.assertEqual(env["VIRTUAL_ENV"], str(task.worktree / ".venv"))
        path = env["PATH"].split(os.pathsep)
        self.assertEqual(path[:2], [str(context.rules_dir(task) / "bin"),  # the git shim first
                                    str(task.worktree / ".venv" / "bin")])
        self.assertNotIn(str(user / "bin"), path)
        from workbench import verify                              # the base check's scratch
        code, said = verify.on_base(task, self.TEST, 60)          # checkout, its setup run again
        self.assertEqual(code, 0, said)
        self.assertNotIn(str(self.repo / "src"), said)
        rules = context.shell_rules(task)                         # into its own venv: no ask
        self.assertEqual(Permission.verdict(rules, "pip install -e ."), "allow")
        self.assertEqual(Permission.verdict(rules, "poetry install"), "allow")

    def test_without_a_setup_the_checkouts_venv_is_left_out_and_wb_start_says_how_to_add_one(self):
        user = self.venv(Path(self.tmp.name) / "elsewhere", self.repo / "src")  # editable only
        bins = self.repo / "node_modules" / ".bin"
        os.environ["PATH"] = f"{os.environ['PATH']}{os.pathsep}{bins}"  # a direnv PATH_add
        out = self.start("t-novenv", "ok", "--test", self.TEST, "--auto-fix", "0", "--no-base-check")
        self.assertIn(f"{user} (an editable install of the repo) is your checkout's", out)
        self.assertIn("--setup 'uv sync' --test 'uv run pytest'", out)
        st = wait_phase("t-novenv", {"review"})
        task = store.Task("t-novenv")
        said = task.round_dir(1).joinpath("tests.txt").read_text()
        self.assertFalse(st["tests"]["ok"])                       # not the checkout's 'user'
        self.assertNotIn(str(self.repo / "src"), said)
        env = runner.agent_env(task)
        self.assertNotIn("VIRTUAL_ENV", env)
        path = env["PATH"].split(os.pathsep)
        self.assertNotIn(str(user / "bin"), path)
        self.assertEqual(path[-1], str(task.worktree / "node_modules" / ".bin"))
        # none active: pip installs where Landlock bounds it, else it asks
        rules = context.shell_rules(task)
        self.assertEqual(Permission.verdict(rules, "pip install -e ."),
                         "allow" if lane.abi() else "deny")

    def test_a_venv_in_a_per_project_home_or_on_path_alone_is_the_checkouts_too(self):
        task = store.Task("t-homes")
        task.dir.mkdir(parents=True)
        (task.dir / "task.json").write_text(json.dumps({"name": "t-homes", "repo": str(self.repo)}))
        workon = Path(self.tmp.name) / "workon"
        os.environ["WORKON_HOME"] = str(workon)
        root = self.venv(workon / "proj")                         # virtualenvwrapper's, not editable
        del os.environ["VIRTUAL_ENV"]                             # found on PATH alone
        self.assertEqual(context.checkout_envs(task), {str(root): "a per-project venv"})
        finder = Path(self.tmp.name) / "conda"                    # setuptools' editable finder
        self.venv(finder)
        site = next(finder.glob("lib/*/site-packages"))
        (site / "__editable___mypkg_0_1_finder.py").write_text(
            f"MAPPING = {{'mypkg': {str(self.repo / 'src' / 'mypkg')!r}}}\n")
        self.assertEqual(context.checkout_envs(task)[str(finder)], "an editable install of the repo")
        (site / "__editable___mypkg_0_1_finder.py").write_text(
            f"MAPPING = {{'mypkg': {str(self.repo) + '-other/src'!r}}}\n")  # another repo
        self.assertNotIn(str(finder), context.checkout_envs(task))

    def test_the_users_pythonpath_reaches_the_setup_and_tests_with_the_repo_as_the_worktree(self):
        # #512 (the audit of 1.90): ROS's setup.bash exports PYTHONPATH; the runner replaced it
        # with workbench's own, the agent's environment dropped that, and naming PYTHONPATH in
        # commands.json `env` passed workbench's package path instead of the user's
        deps = Path(self.tmp.name) / "opt" / "ros"
        deps.mkdir(parents=True)
        (deps / "rclpy.py").write_text("OK = True\n")
        os.environ["PYTHONPATH"] = os.pathsep.join([str(deps), str(self.repo / "src"),
                                                    str(context.PKG_ROOT)])
        Path(os.environ["WB_COMMANDS"]).write_text(json.dumps({"env": ["PYTHONPATH"]}))
        check = ("python3 -c \"import importlib.util as u, rclpy, mypkg, sys; print(mypkg.__file__); "
                 "sys.exit(mypkg.VALUE != 'base' or u.find_spec('workbench') is not None)\"")
        self.start("t-pypath", "ok", "--setup", "python3 -c 'import rclpy'", "--test", check,
                   "--auto-fix", "0", "--no-base-check")
        st = wait_phase("t-pypath", {"review"})
        task = store.Task("t-pypath")
        said = task.round_dir(1).joinpath("tests.txt").read_text()
        self.assertTrue(st["tests"]["ok"], said)                  # rclpy, and the worktree's mypkg
        self.assertIn(str(task.worktree / "src" / "mypkg"), said)
        with mock.patch.dict(os.environ, context.detached_env()):   # as spawn_runner leaves it
            env = runner.agent_env(task)
        self.assertEqual(env["PYTHONPATH"], os.pathsep.join([str(deps), str(task.worktree / "src")]))
        self.assertNotIn(context.USER_PYTHONPATH, env)
        os.environ.pop("PYTHONPATH")                              # none: none for the agent either
        with mock.patch.dict(os.environ, context.detached_env()):
            self.assertNotIn("PYTHONPATH", runner.agent_env(task))

    def test_a_venv_that_isnt_the_checkouts_stays_but_the_agent_may_not_install_into_it(self):
        envs = Path(self.tmp.name) / "envs"
        Path(os.environ["WB_COMMANDS"]).write_text(json.dumps({"paths": [str(envs)]}))
        tools = self.venv(envs / "tools")                         # pytest and ruff, no project
        (envs / "scratch").mkdir()
        self.assertNotIn("is your checkout's", self.start("t-tools", "ok"))
        wait_phase("t-tools", {"review"})
        task = store.Task("t-tools")
        env = runner.agent_env(task)
        self.assertEqual(env["VIRTUAL_ENV"], str(tools))
        self.assertIn(str(tools / "bin"), env["PATH"].split(os.pathsep))
        rules = context.shell_rules(task)
        for cmd in ("pip install -e .", "python3 -m pip install -r requirements.txt",
                    "poetry install", "pip uninstall -y mypkg", "uv pip sync requirements.txt"):
            self.assertEqual(Permission.verdict(rules, cmd), "deny", cmd)
        self.assertEqual(Permission.verdict(rules, "npm ci"), "allow")
        lane_ = context.writable(task)                            # granted, but not the venv
        self.assertIn(str(envs / "scratch"), lane_)
        self.assertFalse(any(p == str(tools) or p.startswith(str(tools) + os.sep) for p in lane_))


class Permission(Base):
    """A refused command: the agent asks with `command`, `wb allow` answers and restarts it."""
    def test_a_request_is_answered_by_wb_allow_outside_the_question_budget(self):
        from workbench import ask_mcp
        self.start("t-perm", "hang", "--ask-budget", "0")
        deadline = time.time() + 20
        while store.Task("t-perm").status.get("phase") != "running" and time.time() < deadline:
            time.sleep(0.2)
        task = store.Task("t-perm")
        self.assertIn("budget for this task is used up", ask_mcp.ask(task, "which file?"))
        got = {}
        t = threading.Thread(target=lambda: got.update(a=ask_mcp.ask(
            task, "to fetch the fixture the spec names", command="curl -sO https://x/f.json")))
        t.start()
        # the relay sets status asking, then writes the notice: wait for the notice (#141)
        deadline = time.time() + 20
        notices = lambda: store.read_jsonl(store.home() / "notify.jsonl")[0]  # noqa: E731
        while not (notices() and "PERMISSION" in notices()[-1]["text"]) and time.time() < deadline:
            time.sleep(0.1)
        self.assertIn("PERMISSION to run: `curl -sO https://x/f.json`", notices()[-1]["text"])
        out = run_wb("allow", "t-perm", "curl *")
        t.join(10)
        self.assertIn("Claude allowed `curl *` for this task", got["a"])
        self.assertIn("restarts on its session", out)
        self.assertEqual(context.grants(task)["allow"], ["curl *"])
        layer = json.loads(Path(runner.write_config_layer(task)).read_text())
        allows = [r["resource"] for r in layer["permissions"]
                  if r["action"] == "shell" and r["effect"] == "allow"]
        self.assertEqual(allows[-1], "curl *")                 # after the defaults and ask-first
        shell = [r for r in layer["permissions"] if r["action"] == "shell"]
        hard = context.denied_shell()
        self.assertEqual([r["resource"] for r in shell[-len(hard):]], list(hard))  # last
        self.assertTrue({"gh *", "env gh *"} <= set(context.DENIED_SHELL))
        run_wb("stop", "t-perm")
        run_wb("allow", "t-perm", "docker *", "--always")
        self.assertEqual(json.loads(Path(os.environ["WB_COMMANDS"]).read_text())["allow"],
                         ["docker *"])

    def test_wb_allow_answers_the_permission_request_not_an_older_plain_question(self):
        # status.asking is the oldest question of any kind: wb allow answered a plain question
        # with its leave and left the request open (the 0.90 review)
        from workbench import ask_mcp
        self.start("t-two-kinds", "ok", "--ask-budget", "3")
        wait_phase("t-two-kinds", {"review"})
        task, opened = store.Task("t-two-kinds"), {}
        task.set_status(phase="running")
        store.write_json(context.ask_dir(task) / "aaaaaaaa.json", {"question": "which file?"})
        ask_mcp.relay(task, opened)
        store.write_json(context.ask_dir(task) / "bbbbbbbb.json",
                         {"question": "to fetch it", "command": "curl -sO https://x/f.json"})
        ask_mcp.relay(task, opened)
        self.assertEqual(task.status["asking"], "aaaaaaaa")
        run_wb("allow", "t-two-kinds", "curl *")
        self.assertTrue(ask_mcp.is_open(task, "aaaaaaaa"))
        self.assertIn("Claude allowed `curl *`",
                      (context.ask_dir(task) / "bbbbbbbb.answer").read_text())

    @staticmethod
    def verdict(rules, command):
        """OpenCode's matcher as CLAUDE.md describes it: anchored, `*` matches anything, `?` one
        character, a trailing ` *` optional, the last matching rule wins."""
        import re as _re
        found = None
        for r in rules:
            pat = r["resource"]
            rx = _re.escape(pat[:-2] if pat.endswith(" *") else pat).replace(r"\*", ".*") \
                .replace(r"\?", ".")
            rx += "( .*)?" if pat.endswith(" *") else ""
            if _re.fullmatch(rx, command, _re.S):
                found = r["effect"]
        return found

    def test_installing_what_the_project_lists_with_its_usual_flags_needs_no_question(self):
        # #671 (the 2026-11-21 audit): `pnpm install --frozen-lockfile` and `pip install -e
        # ".[dev]"` were refused, though the bare forms were the agent's
        task = store.Task("t-flags")
        task.dir.mkdir(parents=True)
        (task.dir / "task.json").write_text(json.dumps({"name": "t-flags", "repo": str(self.repo)}))
        rules = context.shell_rules(task)
        for cmd in ("pnpm install --frozen-lockfile", "npm install --legacy-peer-deps",
                    "bun install --frozen-lockfile", "npm i --no-audit", "pnpm i --offline",
                    "npm install --production", "bun install --immutable"):
            self.assertEqual(self.verdict(rules, cmd), "allow", cmd)
        # #916 (the third 2026-11-21 audit): the common CI lines with two flags, and npm's
        # --no-fund, still asked first
        for cmd in ("pnpm install --frozen-lockfile --prefer-offline", "npm i --no-audit --no-fund",
                    "npm install --no-audit --prefer-offline", "npm install --no-fund",
                    "bun install --frozen-lockfile --production",
                    "CI=1 pnpm install --frozen-lockfile --ignore-scripts"):
            self.assertEqual(self.verdict(rules, cmd), "allow", cmd)
        for cmd in ("pnpm install --frozen-lockfile lodash", "npm install --legacy-peer-deps x",
                    "npm install left-pad", "bun install --prod zod",
                    "npm i --no-audit --no-fund left-pad",
                    "pnpm install --frozen-lockfile --prefer-offline lodash"):
            self.assertEqual(self.verdict(rules, cmd), "deny", cmd)       # a new package asks
        pip = self.verdict(rules, "pip install -e .")    # allowed where pip's install is bounded
        for cmd in ('pip install -e ".[dev]"', "pip install -e .[dev,test]",
                    "python3 -m pip install -e '.[all]'", 'uv pip install -e ".[dev]"'):
            self.assertEqual(self.verdict(rules, cmd), pip, cmd)
        self.assertEqual(self.verdict(rules, "pip install -e .[dev] requests"), "deny")

