    @unittest.skipUnless(shutil.which("ssh-keygen"), "needs ssh-keygen")
    def test_a_key_that_needs_unlocking_is_said_at_start_and_accept_says_how(self):
        # #374 (the audit of 1.6, reproduced): with commit.gpgsign and a passphrase no agent
        # held, wb accept failed after the whole task, blaming an "incorrect passphrase"
        key = Path(self.tmp.name) / "signing"
        subprocess.run(["ssh-keygen", "-q", "-t", "ed25519", "-N", "a passphrase", "-f", str(key)],
                       check=True)
        for k, v in (("gpg.format", "ssh"), ("user.signingkey", str(key)), ("commit.gpgsign", "true")):
            subprocess.run(["git", "-C", str(self.repo), "config", k, v], check=True)
        os.environ.pop("SSH_AUTH_SOCK", None)
        out = self.start("t-sign", "ok")
        self.assertIn("commits here are signed and the key needs unlocking first: ssh-add", out)
        wait_phase("t-sign", {"review"})
        t0 = time.monotonic()
        err = self.refused("accept", "t-sign", "-m", "feat: answer")
        self.assertLess(time.monotonic() - t0, 30)                 # no waiting on a prompt
        self.assertIn("not committed: commits here are signed", err)
        self.assertIn("--no-sign", err)
        run_wb("accept", "t-sign", "-m", "feat: answer", "--no-sign")
        branch = store.Task("t-sign").spec["branch"]
        body = subprocess.run(["git", "-C", str(self.repo), "cat-file", "commit", branch],
                              capture_output=True, text=True, check=True).stdout
        self.assertNotIn("gpgsig", body)
        # a key that signs unattended: no word at start, and the commit is signed
        bare = Path(self.tmp.name) / "signing-bare"
        subprocess.run(["ssh-keygen", "-q", "-t", "ed25519", "-N", "", "-f", str(bare)], check=True)
        subprocess.run(["git", "-C", str(self.repo), "config", "user.signingkey", str(bare)], check=True)
        out = self.start("t-sign2", "ok")
        self.assertNotIn("needs unlocking", out)
        wait_phase("t-sign2", {"review"})
        run_wb("accept", "t-sign2", "-m", "feat: answer")
        body = subprocess.run(["git", "-C", str(self.repo), "cat-file", "commit",
                               store.Task("t-sign2").spec["branch"]],
                              capture_output=True, text=True, check=True).stdout
        self.assertIn("gpgsig", body)

    @unittest.skipUnless(shutil.which("ssh-keygen") and hasattr(os, "login_tty"), "needs ssh-keygen, a pty")
    def test_a_locked_key_is_refused_at_once_even_when_wb_has_a_controlling_terminal(self):
        # #933 (an outside review of v1.90.24; every WSL2 nightly): with a terminal of its own,
        # ssh-keygen prompted on /dev/tty for a passphrase nobody typed, so the dry signature
        # took SIGN_SECS and the signed commit COMMIT_SECS before either refused
        key = Path(self.tmp.name) / "locked"
        subprocess.run(["ssh-keygen", "-q", "-t", "ed25519", "-N", "a passphrase", "-f", str(key)],
                       check=True)
        repo = Path(self.tmp.name) / "signed-repo"
        g = lambda *a: subprocess.run(["git", "-C", str(repo), *a], check=True)  # noqa: E731
        subprocess.run(["git", "init", "-q", str(repo)], check=True)
        g("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-q", "--allow-empty", "-m", "base")
        for k, v in (("user.email", "t@t"), ("user.name", "t"), ("gpg.format", "ssh"),
                     ("user.signingkey", str(key)), ("commit.gpgsign", "true")):
            g("config", k, v)
        (repo / "new.txt").write_text("new\n")
        out = Path(self.tmp.name) / "tty-result.json"
        code = ("import json, sys, time; sys.path.insert(0, sys.argv[1]); from workbench import gitops\n"
                "repo, t0 = gitops.Path(sys.argv[2]), time.monotonic()\n"
                "said = gitops.sign_problem(repo, 'HEAD'); t1 = time.monotonic()\n"
                "try:\n    gitops.commit_all(repo, 'feat: new'); err = None\n"
                "except gitops.GitError as e:\n    err = str(e)\n"
                "open(sys.argv[3], 'w').write(json.dumps({'said': said, 'sign': t1 - t0,"
                " 'commit': time.monotonic() - t1, 'err': err}))\n")
        master, slave = os.openpty()
        env = {k: v for k, v in os.environ.items() if k != "SSH_AUTH_SOCK"}
        try:   # the child's controlling terminal is the pty, as wb's is on WSL2
            p = subprocess.Popen([sys.executable, "-c", code, str(ROOT), str(repo), str(out)],
                                 env=env, pass_fds=(slave,), preexec_fn=lambda: os.login_tty(slave))
            os.close(slave)
            self.assertEqual(p.wait(timeout=200), 0)
        finally:
            os.close(master)
        got = json.loads(out.read_text())
        self.assertEqual(got["said"], gitops.UNLOCK)
        self.assertLess(got["sign"], gitops.SIGN_SECS / 2)
        self.assertIn("not committed: commits here are signed", got["err"])
        self.assertLess(got["commit"], 30)

    def test_a_signer_that_asks_for_a_touch_gets_no_dry_signature_and_is_told_apart_from_ssh_add(self):
        # #528 (the audit of v1.90): the dry signature made a security key blink on every wb
        # start, and on a timeout advised ssh-add, which can't make a touch-required key sign
        g = lambda *a: subprocess.run(["git", "-C", str(self.repo), *a], check=True)  # noqa
        pub = Path(self.tmp.name) / "id_ed25519_sk.pub"
        pub.write_text("sk-ssh-ed25519@openssh.com AAAAGnNrLXNzaC1lZDI1NTE5QG9wZW5zc2guY29t x@y\n")
        signed = Path(self.tmp.name) / "signed"
        prog = Path(self.tmp.name) / "signer"
        prog.write_text(f"#!/bin/sh\necho >> {signed}\nexit 1\n")
        prog.chmod(0o755)
        for k, v in (("gpg.format", "ssh"), ("user.signingkey", str(pub)), ("commit.gpgsign", "true")):
            g("config", k, v)
        out = self.start("t-touch", "ok")
        self.assertIn("signed by a security key (an sk- SSH key), which asks for a touch", out)
        self.assertIn("--no-sign commits unattended", out)
        self.assertNotIn("ssh-add", out)
        g("config", "user.signingkey", "key::ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIA x@y")
        g("config", "gpg.ssh.program", str(prog))   # an op-ssh-sign: asks on each use
        out = self.start("t-touch2", "ok", "--queue")
        self.assertIn("signed by signer (gpg.ssh.program)", out)
        self.assertFalse(signed.exists())                          # no dry signature asked for
        wait_phase("t-touch2", {"review"})
        err = self.refused("accept", "t-touch2", "-m", "feat: answer")
        self.assertIn("asks for a touch or an approval: none came; or --no-sign", err)
        self.assertNotIn("ssh-add", err)
        # an OpenPGP key on a card: gpg lists it with the card's serial number
        gpg = Path(self.tmp.name) / "gpg"
        row = ["sec", "u", "255", "22", "ABCDEF0123456789", "1700000000", "", "", "u", "", "",
               "scESC", "", "", "D2760001240100000006", "", ""]
        gpg.write_text(f"#!/bin/sh\necho '{':'.join(row)}'\n")
        gpg.chmod(0o755)
        for k in ("gpg.format", "user.signingkey", "gpg.ssh.program"):
            g("config", "--unset", k)
        g("config", "gpg.program", str(gpg))
        self.assertIn("signed by an OpenPGP card", gitops.sign_problem(self.repo, "HEAD"))
        row[14] = "+"                                                # a key on disk: dry-run
        gpg.write_text(f"#!/bin/sh\necho '{':'.join(row)}'\nexit 1\n")
        self.assertIsNone(gitops.presence_signer(self.repo))

    def test_ssh_signing_whose_key_comes_from_a_default_key_command_starts_without_a_traceback(self):
        # #662: no user.signingkey (gpg.ssh.defaultKeyCommand picks the key) built Path(""), and
        # its .pub raised a ValueError past main: every wb start was a traceback
        g = lambda *a: subprocess.run(["git", "-C", str(self.repo), *a], check=True)  # noqa
        os.environ.pop("SSH_AUTH_SOCK", None)                       # never the user's agent
        for k, v in (("gpg.format", "ssh"), ("gpg.ssh.defaultKeyCommand", "true"),
                     ("commit.gpgsign", "true")):
            g("config", k, v)
        self.assertIsNone(gitops.presence_signer(self.repo))
        gitops.sign_problem(self.repo, "HEAD")                     # says what it says, no raise
        self.assertIn("started t-dkc", self.start("t-dkc", "ok", "--queue"))

    def test_a_monorepo_package_with_its_own_claude_md_is_where_the_agent_and_tests_run(self):
        # #375 (the audit of 1.6, reproduced): from packages/app, whose CLAUDE.md Claude Code reads,
        # wb start refused the repo for a CLAUDE.md at its root, and the agent worked from the root
        g = lambda *a: subprocess.run(["git", "-C", str(self.repo), *a], check=True)  # noqa
        app, lib = self.repo / "packages" / "app", self.repo / "packages" / "lib"
        for d in (app, lib):
            d.mkdir(parents=True)
        (app / "CLAUDE.md").write_text("# app\nThe app package.\n")
        (app / "app.marker").write_text("")
        (lib / "lib.txt").write_text("")
        g("rm", "-q", "CLAUDE.md")
        g("add", "-A")
        g("commit", "-qm", "two packages, no root CLAUDE.md")
        runs = Path(self.tmp.name) / "runs.jsonl"
        os.environ["FAKE_RUNS"] = str(runs)
        os.environ["FAKE_SCENARIO"] = "ok"
        out = run_wb("start", "t-pkg", "--spec", str(self.spec), "--repo", str(app), "--model", "mimo",
                     "--test", "test -f app.marker && test -f answer.txt")
        self.assertIn("package: packages/app", out)
        st = wait_phase("t-pkg", {"review"})
        task = store.Task("t-pkg")
        self.assertEqual(task.spec["subdir"], "packages/app")
        first = json.loads(runs.read_text().splitlines()[0])
        self.assertEqual((first["cwd"], first["pwd"]), (str(task.workdir), str(task.workdir)))
        self.assertTrue(st["tests"]["ok"])                     # the tests ran in the package
        from workbench import context
        files, nested = context.instruction_files(task)
        self.assertIn(task.worktree / "packages" / "app" / "CLAUDE.md", files)
        self.assertNotIn("packages/app/CLAUDE.md", nested)
        (task.workdir / "AGENTS.md").write_text((app / "CLAUDE.md").read_text())  # OpenCode loads it
        self.assertNotIn(task.workdir / "CLAUDE.md", context.instruction_files(task)[0])
        self.assertIn("packages/app/answer.txt", run_wb("diff", "t-pkg"))  # the diff: the whole repo's
        # a plain subdirectory still means the whole repo
        g("checkout", "-q", "HEAD~1", "--", "CLAUDE.md")
        g("commit", "-qm", "root CLAUDE.md again")
        run_wb("start", "t-lib", "--spec", str(self.spec), "--repo", str(lib), "--model", "mimo")
        self.assertNotIn("subdir", store.Task("t-lib").spec)

    def test_each_monorepo_package_gets_its_own_commands_json_entry_not_the_first_in_the_file(self):
        # #778: no key equalled the repo's root, so the git-dir fallback took the first entry, a
        # package's: the api task ran web's `pnpm install` and accept squashed by web's `merge`
        g = lambda *a: subprocess.run(["git", "-C", str(self.repo), *a], check=True)  # noqa
        web, api = self.repo / "packages" / "web", self.repo / "services" / "api"
        for d in (web, api):
            d.mkdir(parents=True)
            (d / "CLAUDE.md").write_text(f"# {d.name}\n")
        g("add", "-A")
        g("commit", "-qm", "two packages")
        Path(os.environ["WB_COMMANDS"]).write_text(json.dumps({"repos": {
            str(web): {"setup": "true web", "merge": "squash"}, str(api): {"setup": "true api"}}}))
        self.assertEqual(context.repo_conf(self.repo, "services/api"), {"setup": "true api"})
        self.assertEqual(context.repo_conf(self.repo, "packages/web")["setup"], "true web")
        self.assertEqual(context.repo_conf(self.repo), {})                  # the root: neither
        self.assertEqual(context.repo_conf(self.repo, "services/other"), {})
        os.environ["FAKE_SCENARIO"] = "ok"
        run_wb("start", "t-api", "--spec", str(self.spec), "--repo", str(api), "--model", "mimo")
        self.assertEqual(store.Task("t-api").spec.get("setup"), "true api")
        # a linked worktree of the repo: the same package's entry, by the path inside it
        wt = Path(self.tmp.name) / "linked"
        g("worktree", "add", "-q", "-b", "feat", str(wt))
        self.assertEqual(context.repo_conf(wt, "services/api"), {"setup": "true api"})
        self.assertEqual(context.repo_conf(wt), {})
        # the root's entry holds for every package without one of its own
        Path(os.environ["WB_COMMANDS"]).write_text(json.dumps({"repos": {
            str(self.repo): {"merge": "ff"}, str(web): {"merge": "squash"}}}))
        self.assertEqual(context.repo_conf(self.repo, "services/api"), {"merge": "ff"})
        self.assertEqual(context.repo_conf(wt, "packages/web"), {"merge": "squash"})
        self.assertEqual(context.repo_conf(wt, "services/api"), {"merge": "ff"})

    def test_accept_in_a_package_measures_the_packages_own_claude_md_not_the_root(self):
        # #783: accept looked at the root only, so a package task in a repo whose root has no
        # CLAUDE.md always ended "the repo has no CLAUDE.md: write one (wb init)"
        g = lambda *a: subprocess.run(["git", "-C", str(self.repo), *a], check=True)  # noqa
        app = self.repo / "packages" / "app"
        app.mkdir(parents=True)
        (app / "CLAUDE.md").write_text("# app\n")
