    def test_vapid_signatures_are_es256_that_openssl_and_push_services_can_check(self):
        from workbench import webpush as wp
        # RFC 6979 A.2.5, P-256 with SHA-256, "sample": the known key, nonce and signature
        d = 0xC9AFA9D845BA75166B5C215767B1D6934E50C3DB36E89B127B8A622B120F6721
        k = 0xA6E3C57DD01ABE90086538398355DD4C3B17AA873382B0F24D6129493D8AAD60
        self.assertEqual(wp.sign(d, b"sample", k).hex().upper(),
                         "EFD48B2AACB6A8FD1140DD9CD45E81D69D2C877B56AAF991C34D0EA84EAF3716"
                         "F7CB1C942D657C41D436C7A1B6E29F65F3E900DBB9AFF4064DC4AB2F843ACDA8")
        q = wp._mul(d, wp.G)
        self.assertEqual(q[0], 0x60FED4BA255A9D31C961EB74C6356D68C049B8923B61FA6CE669622E60F29FB6)
        sig = wp.sign(d, b"hello")
        self.assertTrue(wp.verify(q, b"hello", sig))
        self.assertFalse(wp.verify(q, b"hellO", sig))
        if not shutil.which("openssl"):
            return
        # openssl checks ours: the key as SubjectPublicKeyInfo, the signature as DER
        tmp = Path(self.tmp.name)
        point = base64.urlsafe_b64decode(wp.public_key(d) + "=")
        (tmp / "pub.der").write_bytes(bytes.fromhex("3059301306072a8648ce3d020106082a8648ce3d030107034200") + point)

        def der_int(b):
            b = b.lstrip(b"\0")
            b = b"\0" + b if b[0] & 0x80 else b
            return b"\x02" + bytes([len(b)]) + b
        body = der_int(sig[:32]) + der_int(sig[32:])
        (tmp / "sig.der").write_bytes(b"\x30" + bytes([len(body)]) + body)
        (tmp / "msg").write_bytes(b"hello")
        r = subprocess.run(["openssl", "dgst", "-sha256", "-verify", tmp / "pub.der", "-keyform", "DER",
                            "-signature", tmp / "sig.der", tmp / "msg"], capture_output=True, text=True)
        self.assertIn("Verified OK", r.stdout, r.stderr)

    def test_a_push_carries_no_payload_and_a_vapid_header_its_key_checks(self):
        from workbench import webpush as wp
        import http.server
        import threading
        got = []

        class Svc(http.server.BaseHTTPRequestHandler):
            def do_POST(self):
                got.append((self.headers, self.rfile.read(int(self.headers["Content-Length"]))))
                self.send_response(201)
                self.end_headers()

            def log_message(self, *a):
                pass
        svc = http.server.HTTPServer(("127.0.0.1", 0), Svc)
        threading.Thread(target=svc.serve_forever, daemon=True).start()
        self.addCleanup(svc.server_close)
        self.addCleanup(svc.shutdown)
        d = wp.private_key(self.chat.token_path())
        self.assertEqual(wp.send(d, f"http://127.0.0.1:{svc.server_address[1]}/sub/1"), (201, ""))
        headers, body = got[0]
        self.assertEqual(body, b"")
        self.assertEqual(headers["TTL"], str(wp.TTL))
        jwt, key = headers["Authorization"].removeprefix("vapid t=").split(", k=")
        self.assertEqual(key, wp.public_key(d))
        head, body64, sig = jwt.split(".")
        claims = json.loads(base64.urlsafe_b64decode(body64 + "=="))
        self.assertEqual(claims["aud"], f"http://127.0.0.1:{svc.server_address[1]}")
        q = base64.urlsafe_b64decode(key + "=")
        q = (int.from_bytes(q[1:33], "big"), int.from_bytes(q[33:], "big"))
        self.assertTrue(wp.verify(q, f"{head}.{body64}".encode(),
                                  base64.urlsafe_b64decode(sig + "==")))
        self.assertEqual(oct(wp.key_path(self.chat.token_path()).stat().st_mode & 0o777), "0o600")

    def test_an_empty_or_broken_vapid_key_file_is_replaced_and_never_stops_the_chat(self):
        # #924: created first and written after, a full disk or a crash left the key file empty,
        # and every snapshot raised: the page said "Can't reach the computer" until it was deleted
        from workbench import webpush as wp
        chat, tok = self.chat, self.chat.token()
        path = wp.key_path(chat.token_path())
        for broken in ("", "zz\n", f"{wp.N:064x}\n"):                  # empty, not hex, out of range
            path.write_text(broken)
            chat._keys.clear()
            d = wp.private_key(chat.token_path())
            self.assertTrue(0 < d < wp.N)
            self.assertEqual(path.read_text(), f"{d:064x}\n")         # replaced, whole
            self.assertEqual(oct(path.stat().st_mode & 0o777), "0o600")
            self.assertEqual(wp.private_key(chat.token_path()), d)  # and kept
        self.assertEqual([p.name for p in path.parent.iterdir() if p.name.endswith(".tmp")], [])
        with mock.patch.object(wp.os, "fsync", side_effect=OSError(28, "No space left on device")):
            path.unlink()
            with self.assertRaises(OSError):
                wp.private_key(chat.token_path())
        self.assertFalse(path.exists())                                # nothing half-written left
        chat._keys.clear()
        with mock.patch.object(wp, "private_key", side_effect=RuntimeError("no usable key")), \
                redirect_stderr(io.StringIO()):
            status, state = self.call("/api/state", token=tok)
            self.assertEqual(status, 200)                              # messaging goes on
            self.assertIsNone(state["push"]["key"])
            self.assertEqual(self.call("/api/send", {"text": "hi"}, token=tok)[0], 200)

    def test_a_vapid_key_is_made_where_the_file_system_has_no_hard_links(self):
        # the review of #924: linked into place, the key was never made on exFAT or a FUSE or SMB
        # mount without hard links (EPERM, ENOTSUP), so push was off for good on such a home
        import errno
        from workbench import webpush as wp
        path = wp.key_path(self.chat.token_path())
        for code in (errno.EPERM, errno.ENOTSUP):
            with contextlib.suppress(FileNotFoundError):
                path.unlink()
            with mock.patch.object(wp.os, "link", side_effect=OSError(code, os.strerror(code))):
                d = wp.private_key(self.chat.token_path())
            self.assertTrue(0 < d < wp.N)
            self.assertEqual(path.read_text(), f"{d:064x}\n")             # renamed into place, whole
            self.assertEqual(oct(path.stat().st_mode & 0o777), "0o600")
            self.assertEqual(wp.private_key(self.chat.token_path()), d)  # and kept
        self.assertEqual([p.name for p in path.parent.iterdir() if p.name.endswith(".tmp")], [])

    def test_devices_subscribe_only_with_a_push_services_address_and_hear_of_news_once(self):
        chat, tok = self.chat, self.chat.token()
        from workbench import webpush as wp
        key = self.call("/api/state", token=tok)[1]["push"]["key"]
        self.assertEqual(len(base64.urlsafe_b64decode(key + "=")), 65)   # an uncompressed P-256 point
        for bad in ("http://fcm.googleapis.com/x", "https://example.com/x", "https://googleapis.com.evil.io/x",
                    "https://127.0.0.1/x", "https://fcm.googleapis.com:8443/x"):
            self.assertEqual(self.call("/api/push", {"endpoint": bad, "on": True}, token=tok)[0], 400, bad)
        good = "https://fcm.googleapis.com/fcm/send/abc"
        self.assertEqual(self.call("/api/push", {"endpoint": good, "on": True})[0], 401)
        self.assertEqual(self.call("/api/push", {"endpoint": good, "on": True}, token=tok)[0], 200)
        self.assertEqual([s["endpoint"] for s in wp.subscriptions()], [good])

        sent = []
        pusher = chat.Pusher(chat.Hub(), send=lambda eps: sent.append(1) or {e: 201 for e in eps})
        seen = chat.send("I saw this one on the page", "claude")
        missed = chat.send("Done: the tests pass.", "claude")
        self.assertEqual(self.call("/api/seen", {"ids": [seen["id"]]}, token=tok)[0], 200)
        self.assertEqual(pusher.tick(missed["ts"] + 1), [])                 # an open page may show it yet
        self.assertEqual(pusher.tick(missed["ts"] + chat.PUSH_DELAY + 1), [missed["id"]])
        self.assertEqual(pusher.tick(missed["ts"] + chat.PUSH_DELAY + 2), [])   # once
        self.assertEqual(len(sent), 1)
        ask = chat.ask("Bash", "make")
        self.assertEqual(pusher.tick(ask["ts"] + chat.PUSH_DELAY + 1), [ask["id"]])
        late = chat.send("old news", "claude")
        self.assertEqual(pusher.tick(late["ts"] + chat.PUSH_WINDOW + 1), [])  # never a backlog

        self.assertEqual(self.call("/api/push", {"endpoint": good, "on": False}, token=tok)[0], 200)
        self.assertEqual(wp.subscriptions(), [])
        wp.subscribe(good)
        with mock.patch.object(wp, "send", return_value=(410, "HTTP 410 Gone")):  # the service says it's gone
            self.assertEqual(wp.push_all(1), {good: (410, "HTTP 410 Gone")})
        self.assertEqual(wp.subscriptions(), [])
        # #86: each device on its own; one its service failed for now is tried again, alone
        flaky = "https://web.push.apple.com/QF"
        wp.subscribe(good)
        wp.subscribe(flaky)
        calls, down = [], [True]
        pusher = chat.Pusher(chat.Hub(), send=lambda eps: calls.append(eps) or {
            e: (503 if down[0] and e == flaky else 201) for e in eps})
        news = chat.send("PERMISSION: may I push?", "claude")
        t = news["ts"] + chat.PUSH_DELAY + 1
        self.assertIn(news["id"], pusher.tick(t))        # with what the new device never had
        self.assertEqual(calls, [[good, flaky]])
        self.assertEqual(pusher.tick(t + 1), [])                           # not before PUSH_RETRY
        down[0] = False
        self.assertIn(news["id"], pusher.tick(t + chat.PUSH_RETRY + 1))
        self.assertEqual(calls[1:], [[flaky]])                             # the phone alone, again
        self.assertEqual(pusher.tick(t + chat.PUSH_RETRY + 2), [])
        self.assertEqual(len(calls), 2)                                    # each device once
        app = self.call("/manifest.webmanifest?k=" + tok)[1]                # the installed app opens keyed
        self.assertEqual(json.loads(app)["start_url"], "/?token=" + tok)
        self.assertEqual(json.loads(self.call("/manifest.webmanifest?k=wrong")[1])["start_url"], "/")
        self.assertEqual(json.loads(self.call("/manifest.webmanifest")[1])["start_url"], "/")
        page = self.call("/sw.js")
        self.assertEqual(page[0], 200)
        self.assertEqual(self.call("/icon-192.png")[0], 200)

    def test_the_notification_badge_is_a_monochrome_image_with_an_alpha_channel(self):
        # #757 (the 2026-11-21 audit, finding 105): Android draws the status-bar badge from the
        # alpha channel alone, and the badge was icon-192.png, RGB with none: a white square
        import struct
        badge = re.search(r"badge: '/([^']+)'", (self.chat.STATIC / "sw.js").read_text()).group(1)
        code, data = self.call("/" + badge)[:2]
        self.assertEqual(code, 200)
        self.assertEqual(data[:8], b"\x89PNG\r\n\x1a\n")
        self.assertEqual(data[12:16], b"IHDR")
        width, height, depth, colour = struct.unpack(">IIBB", data[16:26])
        self.assertEqual((colour, depth), (6, 8))          # RGBA
        self.assertLessEqual(width, 96)

    def test_a_push_that_fails_says_why_in_the_log_and_on_the_page_and_a_refusal_is_not_delivered(self):
        # #539 (the 2026-11-20 audit, reproduced with an empty SSL_CERT_FILE): send returned 0 with
        # the reason dropped, the page blamed the push service, serve.log stayed empty, the push was
        # retried for 15 minutes, and a 403 was written down as delivered
        chat, tok = self.chat, self.chat.token()
        from workbench import webpush as wp
        import http.server
        import ssl
        import threading
        tmp = Path(self.tmp.name)
        subprocess.run(["openssl", "req", "-x509", "-newkey", "ec", "-pkeyopt", "ec_paramgen_curve:P-256",
                        "-nodes", "-keyout", tmp / "k.pem", "-out", tmp / "c.pem", "-days", "1",
                        "-subj", "/CN=localhost"], check=True, capture_output=True)

        class Svc(http.server.BaseHTTPRequestHandler):
            def do_POST(self):
                self.send_response(201)
                self.end_headers()

            def log_message(self, *a):
                pass
        svc = http.server.HTTPServer(("127.0.0.1", 0), Svc)
        tls = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
        tls.load_cert_chain(tmp / "c.pem", tmp / "k.pem")
        svc.socket = tls.wrap_socket(svc.socket, server_side=True)
        threading.Thread(target=svc.serve_forever, daemon=True).start()
        self.addCleanup(svc.server_close)
        self.addCleanup(svc.shutdown)
        status, why = wp.send(wp.private_key(chat.token_path()), f"https://localhost:{svc.server_address[1]}/sub")
        self.assertEqual(status, wp.CERT)                                    # a certificate it can't check
        self.assertIn("certificate", why)
        self.assertFalse(chat._transient(wp.CERT))                         # for good, not tried for 15 minutes

        phone, desk = "https://web.push.apple.com/phone", "https://fcm.googleapis.com/fcm/send/desk"
        wp.subscribe(phone)
        wp.subscribe(desk)
        answers = {phone: (wp.CERT, why), desk: (403, "HTTP 403 Forbidden")}
        hub = chat.Hub()
        self.addCleanup(hub.close)
        pusher = chat.Pusher(hub, send=lambda eps: {e: answers[e] for e in eps})
        news = chat.send("Done", "claude")
        err = io.StringIO()
        with redirect_stderr(err):
            self.assertEqual(pusher.tick(news["ts"] + chat.PUSH_DELAY + 1), [])  # nothing went
            again = chat.send("Again", "claude")
            pusher.tick(again["ts"] + chat.PUSH_DELAY + 1)
        log = err.getvalue().splitlines()
        self.assertEqual(len(log), 2, log)                                   # each reason once
        self.assertIn("web.push.apple.com failed: certificate not verified", log[0])
        self.assertIn("fcm.googleapis.com failed: HTTP 403 Forbidden", log[1])
        self.assertEqual(pusher.retry_at, {})
        rows = [r for r in store.read_jsonl(chat.chat_dir() / "seen.jsonl")[0] if r["id"] == news["id"]]
        self.assertEqual(sorted((r["by"], r["status"]) for r in rows), [("refused", wp.CERT), ("refused", 403)])

        for got, hint in (({phone: (wp.CERT, why)}, "cert"), ({phone: (403, "HTTP 403 Forbidden")}, "clock"),
                          ({phone: (0, "timed out")}, "unreached"), ({phone: (400, "HTTP 400")}, "refused"),
                          ({phone: (201, ""), desk: (403, "x")}, "")):
            with mock.patch.object(wp, "push_all", return_value=got):
                j = self.call("/api/push", {"test": True}, token=tok)[1]
            self.assertEqual(j["hint"], hint, got)
        self.assertEqual(j["reasons"], ["x"])
        with mock.patch.object(wp, "has_cas", return_value=False):          # wb doctor says it, with a fix
            buf = io.StringIO()
            with redirect_stdout(buf), contextlib.suppress(SystemExit):
                cli.main(["doctor"])
        self.assertIn("BAD web chat notifications: this Python has no CA certificates", buf.getvalue())
        self.assertTrue(wp.has_cas())                                        # this machine's has them

    def test_a_page_only_on_screen_silences_its_own_devices_push_and_not_the_phones(self):
        # #537 (the 2026-11-20 audit): a desktop tab left open behind the terminal reported what
        # it showed for every device, so the phone was never notified
        chat, tok = self.chat, self.chat.token()
        from workbench import webpush as wp
        desk, phone = "https://fcm.googleapis.com/fcm/send/desk", "https://web.push.apple.com/phone"
        wp.subscribe(desk)
        wp.subscribe(phone)
        calls = []
        hub = chat.Hub()
        self.addCleanup(hub.close)
        pusher = chat.Pusher(hub, send=lambda eps: calls.append(eps) or {e: 201 for e in eps})
        news = chat.send("Done: ready for review", "claude")
