    def test_wsl_finds_its_nvidia_smi_when_path_lacks_it(self):
        # the 2026-11-19 audit: under a systemd unit WSL's /usr/lib/wsl/lib isn't on PATH, and the
        # GPU went unseen
        line = "GPU-5e1f, NVIDIA GeForce RTX 4090, 24564, 1000, 560.94"
